import{_ as o,o as r,c as t,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Reseller Payouts Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Reseller Payouts Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/reseller-payouts-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Reseller Payouts Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/reseller-payouts-overview"}]]},"headers":[],"relativePath":"user-guide/reseller-payouts-overview.md","filePath":"user-guide/reseller-payouts-overview.md","lastUpdated":1787349040000}'),l={name:"user-guide/reseller-payouts-overview.md"};function s(i,e,d,n,c,u){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="reseller-payouts-module" tabindex="-1">Reseller Payouts Module <a class="header-anchor" href="#reseller-payouts-module" aria-label="Permalink to &quot;Reseller Payouts Module&quot;">​</a></h1><p>Phase 1 Sales companion to <a href="/user-guide/resellers-overview">Resellers</a>. Maintains a <strong>commission ledger</strong> (<code>reseller_commission_entries</code>) with two parties per paid invoice — reseller and owner — and an accrued → approved → paid (or void) workflow.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/reseller-payouts">reseller-payouts.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/reseller-payouts">reseller-payouts.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/reseller-payouts">reseller-payouts.md</a></td></tr><tr><td>Related module</td><td><a href="/user-guide/resellers-overview">Resellers</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-reseller-payouts">../api/tenant-v1-reseller-payouts.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Accrues <strong>two</strong> ledger rows when a customer invoice with <code>reseller_id</code> becomes fully <strong>Paid</strong></li><li>Parties: <code>reseller</code> (rate = reseller <code>commission_rate</code>) and <code>owner</code> (rate = reseller <code>owner_commission_rate</code>)</li><li>Status workflow: <code>accrued</code> → <code>approved</code> → <code>paid</code>; <code>void</code> from accrued/approved (not from paid)</li><li>Auto-void non-paid entries when an invoice <strong>leaves</strong> Paid status</li><li>List/stats with search, status, party, and reseller filters</li><li>Module licensing (<code>module:reseller-payouts</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong></li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>reseller-payouts.view</code> · <code>approve</code> · <code>pay</code> · <code>void</code></p><p>Catalog: slug <code>reseller-payouts</code>, category <code>sales</code> (Sales), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 80</code>. Hard dependency: <strong>Resellers</strong>.</p><h2 id="commission-formula" tabindex="-1">Commission formula <a class="header-anchor" href="#commission-formula" aria-label="Permalink to &quot;Commission formula&quot;">​</a></h2><p>For invoice total <code>T</code>, reseller rate <code>R%</code>, owner rate <code>O%</code>:</p><ul><li>Reseller amount = <code>round(T × R / 100, 2)</code></li><li>Owner amount = <code>round((T − reseller amount) × O / 100, 2)</code></li></ul><p>Accrual is idempotent via unique <code>(customer_invoice_id, party)</code>.</p><h2 id="required-dependency" tabindex="-1">Required dependency <a class="header-anchor" href="#required-dependency" aria-label="Permalink to &quot;Required dependency&quot;">​</a></h2><p>Reseller Payouts <strong>requires Resellers</strong>. Install Resellers (and therefore Payments) first.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Cross-workspace identity for payout parties</li><li>Automated bank / Stripe Connect disbursement</li><li>Partial payment commission (accural is <strong>fully Paid only</strong>, not Partial)</li><li>Recalculation when commission rates change after accrual</li></ul>',17)])])}const h=o(l,[["render",s]]);export{m as __pageData,h as default};
